def is_not_prime(numbers):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    return [not is_prime(num) for num in numbers]

import heapq

def heap_queue_largest(numbers):
    return heapq.nlargest(3, numbers)

def find_Rotations(s: str) -> int:
    n = len(s)
    for i in range(1, n+1):
        # Rotate string by i positions
        rotated = s[i:] + s[:i]
        if rotated == s:
            return i
    return n  # fallback, though it should always return before this

import re

def text_lowercase_underscore(text):
    sequences = re.findall(r'[a-zA-Z]+', text)
    return '_'.join(seq.lower() for seq in sequences)

def test_duplicate(arr):
    seen = set()
    duplicates = set()
    for item in arr:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)
    return list(duplicates)

def is_woodall(num: int) -> bool:
    if num < 1:
        return False
    n = 1
    while True:
        woodall_num = n * (2 ** n) - 1
        if woodall_num == num:
            return True
        if woodall_num > num:
            return False
        n += 1

def opposite_Signs(a, b):
    # zero is neither positive nor negative
    if a == 0 or b == 0:
        return False
    # return True if one is positive and the other is negative
    return (a > 0 and b < 0) or (a < 0 and b > 0)

def count_Substrings(s: str) -> int:
    count = 0
    n = len(s)
    for i in range(n):
        sum_digits = 0
        for j in range(i, n):
            sum_digits += int(s[j])
            length = j - i + 1
            if sum_digits == length:
                count += 1
    return count

def recursive_list_sum(lst):
    if not lst:
        return 0
    return lst[0] + recursive_list_sum(lst[1:])

def is_Monotonic(array):
    if not array:
        return True
    increasing = decreasing = True
    for i in range(1, len(array)):
        if array[i] < array[i-1]:
            increasing = False
        if array[i] > array[i-1]:
            decreasing = False
    return increasing or decreasing

def comb_sort(arr):
    gap = len(arr)
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted = True
        i = 0
        while i + gap < len(arr):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False
            i += 1
    return arr
